alter table card_ideas add column if not exists pinned boolean not null default false;
update card_ideas set pinned = false;
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'call-a-friend' and idea = 'Match friendship style to your friend: talk over coffee or do an activity together. Face-to-face contact best maintains friendships.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'plan-your-time' and idea = 'Treat rest as a scheduled need, not a reward. List activities that genuinely restore you and add one small recovery block to your week.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'be-a-hugger' and idea = 'Try a consensual, comfortable hug lasting about five to ten seconds. It is the duration researchers found most beneficial for reducing stress and anxiety.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'take-the-stairs' and idea = 'Use stairwells between tasks for short, brisk climbs. Repeating this a few times daily can interrupt long sitting periods.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'use-names' and idea = 'Hearing your own name activates attention and identity-related brain regions. Use it occasionally before a key message.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'less-social-media' and idea = 'Reduce social-media use by at least 30 minutes a day for two weeks. Use the freed time to meet or call a friend in person.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'smile' and idea = 'Take a few slow breaths, relax your jaw, and let a soft, effortless smile form while thinking of someone who makes you smile.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'be-grateful' and idea = 'Write down one thing you appreciate each morning or evening. The study found links with lower stress, anxiety, tiredness, and loneliness lasting up to six days.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'give-a-compliment' and idea = 'Offer a brief, genuine compliment to someone you don’t know well. Small kind gestures can create connection and lift your mood.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'plan-your-day' and idea = 'Each evening, choose no more than three concrete tasks for tomorrow and keep them visible. A four-week study found this improved completion, focus, and motivation.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'andy-rooney' and idea = 'Keep doing the work even when you feel low or far from your goal. Small repeated effort builds patience and progress.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'oprah-winfrey' and idea = 'Pause before blaming, then name your own role and pick one solution.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'mahatma-gandhi' and idea = 'Act consistently with your authentic values and preferences. Create a “values tattoo” that visually captures what matters most.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'viktor-frankl' and idea = 'Review past achievements, unfinished goals, regrets, and lessons to create meaning and purpose.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'dalai-lama' and idea = 'Spend five minutes breathing and accepting the day as it is, then write three things you are grateful for.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'mark-manson' and idea = 'Happiness is a side effect of doing the right things for the right reasons, not a target to chase.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'richard-branson' and idea = 'Use happiness as your main success measure, not income or status. Treat money as a tool, not the goal.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'zig-ziglar' and idea = 'Treat happiness as a direction you move toward through habits, empathy, and purpose—not a fixed state to reach.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'denis-waitley' and idea = 'Notice when you are performing an identity for others’ expectations. Practice one small act of honest self-expression this week.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'james-clear' and idea = 'Use a specific memory of genuine thanks, then recall its emotional details for one to five minutes. Story-based gratitude may be more engaging than simply listing items.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'jordan-peterson' and idea = 'Treat effort, friction and small completed steps as evidence that you are progressing, rather than waiting until a task is finished to feel rewarded.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'jordan-belfort' and idea = 'Affirmations can help shift your mindset, but they work best when paired with situations where you practice and build confidence.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'steve-jobs' and idea = 'Start each day by asking whether you would be proud of how you spend it, then choose one meaningful task and give it full attention.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'leonardo-dicaprio' and idea = 'List activities that feel easy, energising and rewarding, then choose one to improve with regular practice.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'meryl-streep' and idea = 'Ask whether a change brings you closer to who you want to be or merely closer to approval.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'johnny-depp' and idea = 'Cut out unnecessary commitments, clutter and distractions so the things that genuinely matter become clearer. Simplicity is not poverty; it is putting first things first.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'will-smith' and idea = 'Treat each day as one brick: do one task well rather than chase a vague big goal. Consistency turns small actions into visible progress.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'jared-leto' and idea = 'Treat low mood as weather: acknowledge it without judging it, then keep doing one small task.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'robert-de-niro' and idea = 'Start a task today even if it is imperfect; progress comes from action, not ideal conditions.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'jennifer-aniston' and idea = 'Recognise recurring reactions or habits, then deliberately replace them with a new response. Knowing yourself helps you see what you love about yourself.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'hugh-jackman' and idea = 'Before starting the day, vividly picture a successful version of it, then write it as if it already happened. Share it with an accountability partner and review it at night.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'keanu-reeves' and idea = 'Identify your core values, then turn them into small goals or actions. Research finds acting on values improves well-being more consistently than reflection alone.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'anthony-hopkins' and idea = 'Leave a familiar routine for one genuinely new activity, even if you may look inexperienced.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'beyonce' and idea = 'Treat yourself as a friend rather than a project to fix. Deliberate self-care and acceptance can create a steadier baseline of contentment.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'wiz-khalifa' and idea = 'Prioritize a small circle of people who genuinely appreciate you over a large social network. Authenticity and mutual respect matter more than popularity.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'harry-styles' and idea = 'Trust a decision when your gut, values, and evidence broadly align; use the 80/20/0 rule.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'chris-martin' and idea = 'Treat a hard day as a challenge to learn from, not a threat to erase. Ask what it is revealing about your values or priorities.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'adam-levine' and idea = 'Changing your behaviour to fit a dominant culture is linked to lower subjective authenticity. It can also weaken the sense of shared reality with your own group.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'katy-perry' and idea = 'Turn setbacks into growth by focusing on resilience and optimism. Perry’s later work shows how personal struggles can become empowering, forward-looking stories.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'mika' and idea = 'Aim for small, hypothesis-driven “intelligent failures” that produce useful information. Design a low-risk experiment, learn from the result, and correct course.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'lizzo' and idea = 'Use short self-compassion podcast episodes to treat setbacks as normal, not proof you are inadequate.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'ryan-tedder' and idea = 'Use a short daily positive exercise, such as writing about a best possible future self. Repeated practice can improve mood and well-being over time.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'madonna' and idea = 'Build happiness through tiny daily habits rather than dramatic life changes. Practice three gratitudes each morning and attach them to an existing routine.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'forrest-gump' and idea = 'When you say you’ll try to change, replace it with a specific commitment and action. Full effort can still fail, but half-hearted attempts rarely change anything.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'rocky' and idea = 'Set a realistic, small goal and celebrate each completion. Small wins build confidence and make the next setback easier to face.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'walt-disney' and idea = 'Choose one action you can take today, then repeat it daily for 30 days. Track the visible change instead of waiting to feel ready.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'august-walker' and idea = 'Keep hope as motivation, but turn it into a realistic plan with preparation for setbacks. Prepare for likely problems rather than relying on a good outcome.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'chris-gardner' and idea = 'Turn vague intentions into a committed next step. Full commitment reduces excuses and keeps you moving toward the goal.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'piglet' and idea = 'Be unapologetically yourself: live in alignment with your true character rather than pretending to be someone else.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'jack-sparrow' and idea = 'Separate the facts from your thoughts, feelings, and actions, then focus only on what you can control.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'donald-duck' and idea = 'True wealth includes calm, genuine laughter, healthy relationships, and peace of mind—not only money or status. Protect those things when making choices.' order by batch_at desc limit 1);
update card_ideas set pinned = true where id = (select id from card_ideas where card_id = 'dumbledore' and idea = 'Protect your attention and stay connected to people and things that bring joy during uncertain times.' order by batch_at desc limit 1);
select count(*) filter (where pinned) as pinned_cards from card_ideas;
